var i=157;var a=`157-cold-sauces-dips-and-spreads`;var s=`154`;var n={en:`Cold Sauces, Dips, and Spreads`,ua:`Холодні соуси, дипи та намазки`};var r={short:`Cold sauces, dips, and spreads vary mainly in how they hold water, fat, and solid particles. Understanding emulsification, blending, and chilling helps control thickness and safe service.`,sections:[{title:`Core idea`,text:`Mayonnaise is an oil-in-water emulsion, hummus is a legume-based paste, and yogurt dip relies on a protein-rich dairy matrix. They require different texture corrections and storage controls.`},{title:`Science`,text:`Droplet size, suspended solids, water content and temperature influence consistency. More oil can thicken a stable mayonnaise, while extra liquid can loosen hummus or yogurt sauce; neither rule should be applied without tasting.`},{title:`How to apply`,text:`Blend ingredients in stages, add liquid in small increments, season after final dilution, and label allergens such as egg, sesame, milk and nuts. Choose pasteurized eggs or an egg-free formula for uncooked egg-based sauces.`},{title:`Practical experiment`,text:`Blend chickpea spread in three versions with different water additions. Compare spreadability after refrigeration; then taste with bread and cucumber to evaluate flavor in context.`},{title:`Common mistakes`,text:`Adding too much liquid in one step makes sauces difficult to correct. A dressing may appear safe and still have been held too warm; maintain cold-chain controls and use clean serving utensils.`},{title:`Related theories`,text:`017, 062, 156, 169.`}]};var l={short:`Холодні соуси, дипи й намазки різняться насамперед тим, як утримують воду, жир та тверді частинки. Розуміння емульгування, подрібнення й охолодження допомагає керувати густотою та безпечно подавати страву.`,sections:[{title:`Суть`,text:`Майонез є емульсією олії у воді, хумус є пастою з бобових, а йогуртовий дип спирається на білкову структуру кисломолочного продукту. Для кожного потрібні власні способи регулювання текстури й зберігання.`},{title:`Наука`,text:`Розмір крапель жиру, кількість твердих частинок, волога й температура впливають на густоту. Додавання олії може загустити стійкий майонез, тоді як вода розріджує хумус; смак треба перевіряти після змін.`},{title:`Як застосувати`,text:`Подрібнюйте поетапно, додавайте рідину малими порціями й коригуйте приправи наприкінці. Позначайте алергени: яйце, кунжут, молоко та горіхи. Для соусів без достатньої термічної обробки використовуйте пастеризовані яйця або без’яєчні рецептури.`},{title:`Практичний дослід`,text:`Приготуйте три зразки хумусу з різною кількістю води. Порівняйте намазуваність після охолодження та сприйняття смаку на хлібі й огірку.`},{title:`Поширені помилки`,text:`Різке додавання великої кількості води призводить до надто рідкої консистенції. Привабливий вигляд не доводить безпечність: холодні соуси потребують чистого інвентарю та належної температури.`},{title:`Пов’язані теорії`,text:`017, 062, 156, 169.`}]};var o=[17,62,156,169];var d=`References / Джерела`;var c=[`https://www.theculinarypro.com/principles-of-sauce-making`,`https://www.fda.gov/food/retail-food-industryregulatory-assistance-training/assuring-safety-eggs-and-menu-and-deli-items-made-raw-shell-eggs`];var u={id:157,slug:a,group:`154`,title:n,en:r,ua:l,related:o,referenceTitle:d,references:c};export{u as default,r as en,s as group,i as id,d as referenceTitle,c as references,o as related,a as slug,n as title,l as ua};